package com.nodecockpit.customization;
import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.view.*;import android.widget.TextView;import java.util.*;
/** Panel styling and500ms refresh adapted from JosephMontfort's MIT ProfessionalDemoActivity.
 * Uses optional Android HWUI GPU/present-fence metrics; never claims compositor shader GPU timing. */
@androidx.annotation.RequiresApi(30)
final class GlassPerformanceHud {
 static java.util.function.Supplier<String> coverage;static boolean enabled,locked;private static final IdentityHashMap<View,Hud> roots=new IdentityHashMap<>();
 static void configure(boolean value){enabled=value;if(!value||locked){for(Hud h:new ArrayList<>(roots.values()))h.destroy();roots.clear();}}
 static void keyguard(boolean value){locked=value;if(value)configure(enabled);}
 static Lease acquire(View view,int layers){if(!enabled||locked||view.getHeight()<180*view.getResources().getDisplayMetrics().density||view.getWidth()<200*view.getResources().getDisplayMetrics().density||!(view instanceof android.view.ViewGroup))return null;Hud h=roots.get(view);if(h==null){try{h=new Hud((android.view.ViewGroup)view);h.start();roots.put(view,h);}catch(Throwable unavailable){android.util.Log.w("GlassHud","HUD unavailable",unavailable);return null;}}h.users++;h.layers+=layers;return new Lease(h,layers);}
 static final class Lease {final Hud h;final int layers;boolean closed;Lease(Hud h,int n){this.h=h;layers=n;}boolean active(){return !closed&&!h.closed;}long bytes,pixels;void allocation(long bufferBytes,long cropPixels){if(active()){h.bytes+=bufferBytes-bytes;h.pixels+=cropPixels-pixels;bytes=bufferBytes;pixels=cropPixels;}}void submission(long cpu){if(active()){h.submissions++;h.cpuNanos+=cpu;}}void close(){if(closed)return;closed=true;if(h.closed)return;h.layers-=layers;h.bytes-=bytes;h.pixels-=pixels;if(--h.users<=0){h.destroy();roots.remove(h.root);}}}
 private static final class Hud implements android.view.ViewTreeObserver.OnDrawListener {
  final android.view.ViewGroup root;final TextView text;GlassFrameObserver frames;final Handler main=new Handler(Looper.getMainLooper());final long[] intervals=new long[180];int cursor,count,users,layers,draws,submissions;long bytes,pixels;long lastDraw,start=SystemClock.elapsedRealtimeNanos(),cpuNanos;boolean closed;
  final Runnable refresh=new Runnable(){public void run(){if(closed)return;if(!enabled||!root.isAttachedToWindow()){destroy();roots.remove(root);return;}long now=SystemClock.elapsedRealtimeNanos();float seconds=Math.max(.001f,(now-start)/1000000000f);long[] values=Arrays.copyOf(intervals,count);Arrays.sort(values);float p95=count==0?0:values[Math.min(count-1,(int)Math.ceil(count*.95)-1)]/1000000f;float cpu=submissions==0?0:cpuNanos/1000000f/submissions;
   text.setText(String.format(Locale.ROOT,"UI draws: %.0f/s · p95 %.1fms\nSubmission CPU: %.2fms · %d/s\nMaterial layers: %d\n%s\nOwned clear buffers: %.1fMiB | crop budget: %.2fMP\n%s\n%s\nGlass shader GPU: not isolated",draws/seconds,p95,cpu,Math.round(submissions/seconds),layers,frames==null?"Frame metrics pending":frames.snapshot(seconds),bytes/1048576.0,pixels/1000000.0,GlassResourceMonitor.snapshot(root.getContext()),coverage==null?"":coverage.get()));layout();draws=submissions=0;cpuNanos=0;start=now;main.postDelayed(this,500);}};
  Hud(android.view.ViewGroup root){this.root=root;float d=root.getResources().getDisplayMetrics().density;text=new TextView(root.getContext());text.setTextColor(0xff4cff7a);text.setTextSize(10);text.setTypeface(Typeface.MONOSPACE);text.setPadding((int)(10*d),(int)(6*d),(int)(10*d),(int)(6*d));GradientDrawable bg=new GradientDrawable();bg.setColor(0xcc000000);bg.setCornerRadius(10*d);text.setBackground(bg);text.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);text.setText("Glass performance\nWaiting for draw samples");}
  void start(){try{frames=new GlassFrameObserver(root,main);root.getOverlay().add(text);layout();root.getViewTreeObserver().addOnDrawListener(this);main.postDelayed(refresh,500);}catch(Throwable t){destroy();throw t;}}
  void layout(){float d=root.getResources().getDisplayMetrics().density;int inset=0;if(root.getRootWindowInsets()!=null)inset=root.getRootWindowInsets().getInsetsIgnoringVisibility(android.view.WindowInsets.Type.statusBars()|android.view.WindowInsets.Type.displayCutout()).top;text.measure(View.MeasureSpec.makeMeasureSpec(Math.max(1,root.getWidth()-(int)(16*d)),View.MeasureSpec.AT_MOST),View.MeasureSpec.makeMeasureSpec(Math.max(1,root.getHeight()/2),View.MeasureSpec.AT_MOST));int x=Math.max(0,root.getWidth()-text.getMeasuredWidth()-(int)(8*d)),y=inset+(int)(8*d);text.layout(x,y,x+text.getMeasuredWidth(),y+text.getMeasuredHeight());}
  public void onDraw(){long now=System.nanoTime();if(lastDraw>0){intervals[cursor]=Math.max(0,now-lastDraw);cursor=(cursor+1)%intervals.length;count=Math.min(intervals.length,count+1);}lastDraw=now;draws++;}
  void destroy(){if(closed)return;closed=true;if(frames!=null){frames.close();frames=null;}main.removeCallbacks(refresh);try{root.getOverlay().remove(text);}catch(Throwable ignored){}try{if(root.getViewTreeObserver().isAlive())root.getViewTreeObserver().removeOnDrawListener(this);}catch(Throwable ignored){}}
 }
}
